% x04_run_sf.m
%
% Runs PsPM SF (spontaneous fluctuation) analysis for all participants.
% Four methods are run per participant, each producing a separate model file:
%   auc  – area under the curve
%   scl  – mean skin conductance level
%   mp   – matching pursuit
%   dcm  – DCM estimate of SF count (most sensitive; requires correct µS units)
%
% Epochs file: {id}_epochs_conditions_psychopy.mat (N×2 matrix of [onset, offset])
% Generated by: 02_create_pspm_onsets_psychopy.py
%
% Run from within MATLAB with PsPM initialised (run pspm first).
% Run order: after x03_preprocess_scr.m and 02_create_pspm_onsets_psychopy.py

% ── Load config ───────────────────────────────────────────────────────────────
REPO_ROOT = fileparts(fileparts(fileparts(mfilename('fullpath'))));

config_path = fullfile(REPO_ROOT, 'config.m');
if ~isfile(config_path)
    error('config.m not found at:\n  %s\nCopy config_template.m to config.m and fill in your paths.', config_path);
end
run(config_path);

if isempty(SERVER_ROOT)
    error('SERVER_ROOT is empty in config.m. Fill in the path to the project root on this machine.');
end

% ── Initialise PsPM ───────────────────────────────────────────────────────────
addpath(PSPM_PATH);
pspm;

% ── Settings ──────────────────────────────────────────────────────────────────
% When called from run_all_pspm.m, the parent script sets SKIP_EXISTING;
% the default here is used only when the script is run standalone.
if ~exist('SKIP_EXISTING', 'var')
    SKIP_EXISTING = false;
end

% Amplitude threshold in µS for DCM SF counting.
% PsPM's recommended range is 0.01–0.05 µS. Verify against Bach et al. or
% PsPM documentation — confirm with Liat/Bach (see NOTES_TO_FOLLOW_UP.md).
THRESHOLD = 0.05;

% Methods to run — comment out any you don't need.
METHODS = {'auc', 'scl', 'mp', 'dcm'};

% ── Paths ─────────────────────────────────────────────────────────────────────
DATA_DIR   = fullfile(SERVER_ROOT, 'pspm', 'preprocessed');
EPOCHS_DIR = fullfile(SERVER_ROOT, 'event_onsets', 'blocks');
MODEL_DIR  = fullfile(SERVER_ROOT, 'pspm', 'models');

% ── Participant IDs ───────────────────────────────────────────────────────────
preprocessed_files = dir(fullfile(DATA_DIR, 'pspm_*_physiology.mat'));

if isempty(preprocessed_files)
    error('No preprocessed files found in:\n  %s\nRun x03_preprocess_scr.m first.', DATA_DIR);
end

participant_ids = cellfun(@(f) regexp(f, '(?<=pspm_)\d+', 'match', 'once'), ...
    {preprocessed_files.name}, 'UniformOutput', false);

fprintf('Found %d participants: %s\n', numel(participant_ids), strjoin(participant_ids, ', '));

% ── Loop over participants and methods ────────────────────────────────────────
for i = 1:numel(participant_ids)
    id = participant_ids{i};

    fprintf('\n=== Processing sub-%s ===\n', id);

    data_file   = fullfile(DATA_DIR,   ['pspm_' id '_physiology.mat']);
    epochs_file = fullfile(EPOCHS_DIR, [id '_epochs_conditions_psychopy.mat']);

    if ~isfile(data_file)
        warning('Data file not found, skipping sub-%s:\n  %s', id, data_file);
        continue
    end
    if ~isfile(epochs_file)
        warning('Epochs file not found, skipping sub-%s:\n  %s', id, epochs_file);
        continue
    end

    for m = 1:numel(METHODS)
        method     = METHODS{m};
        model_name = [id '_sf_' method '_model'];
        model_file = fullfile(MODEL_DIR, [model_name '.mat']);

        if SKIP_EXISTING && isfile(model_file)
            fprintf('  Skipping %s (already exists).\n', model_name);
            continue
        end

        fprintf('  Running %s ...\n', method);

        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.datafile                           = {data_file};
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.output.file                        = model_name;
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.output.dir                         = {MODEL_DIR};
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.output.overwrite                   = 2;
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.method                             = method;
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.timeunits.seconds.epochs.epochfile = {epochs_file};
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.filter.def                         = 0;
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.chan.chan_def                       = 0;
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.threshold                          = THRESHOLD;
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.missing.no_epochs                  = 0;
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.theta                              = [];
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.fresp                              = [];
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.dispwin                            = 1;
        matlabbatch{1}.pspm{1}.first_level{1}.scr{1}.sf.dispsmallwin                       = 0;

        try
            cfg_util('run', matlabbatch);
            fprintf('  Done: %s\n', model_name);
        catch ME
            warning('  Error running %s for sub-%s:\n  %s', method, id, ME.message);
        end

        clear matlabbatch
    end
end

fprintf('\n=== SF complete ===\n');
fprintf('Models saved to: %s\n', MODEL_DIR);
